import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CGSzHL4z.js";const p=JSON.parse('{"title":"Hidden things","description":"","frontmatter":{},"headers":[],"relativePath":"reference/hidden.md","filePath":"reference/hidden.md","lastUpdated":1791952279000}'),i={name:"reference/hidden.md"};function r(n,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="hidden-things" tabindex="-1">Hidden things <a class="header-anchor" href="#hidden-things" aria-label="Permalink to &quot;Hidden things&quot;">​</a></h1><p>Easy-to-miss controls and tricks.</p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><h4 id="keys-that-do-two-jobs" tabindex="-1">Keys that do two jobs <a class="header-anchor" href="#keys-that-do-two-jobs" aria-label="Permalink to &quot;Keys that do two jobs&quot;">​</a></h4><ul><li><strong><kbd>Space</kbd></strong>: tap it to play or pause, hold it and drag to pan. <ul><li>The tap works with the viewport, the Timeline, Hub or the Inspector focused.</li><li>Not while typing, and not with no scene open.</li><li>The status bar says &quot;Space held: drag to pan&quot; while it is armed.</li></ul></li><li><strong><kbd>Alt</kbd> means &quot;no snapping&quot; everywhere</strong>: scrubbing the ruler (lands between frames), key and marker drags, region and scene-end drags, scale handles, sound and effect bar edges, ease handles (Alt ignores the Shift snap).</li><li>Spread uses <kbd>Alt</kbd> for exact ticks instead of whole frames.</li><li><strong><kbd>Tab</kbd> is a three-stop cycle</strong>: Dope sheet, Ease view, Channels view, back to the dope sheet. In Split it swaps the lower part between Ease and Channels.</li><li><strong><kbd>E</kbd></strong> opens the Ease window for the selected keys without going to the Ease view.</li></ul><h4 id="double-click-does-a-lot" tabindex="-1">Double click does a lot <a class="header-anchor" href="#double-click-does-a-lot" aria-label="Permalink to &quot;Double click does a lot&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Double click</th><th>What it does</th></tr></thead><tbody><tr><td>A row header</td><td>Keys the row at the playhead.</td></tr><tr><td>Empty lane space</td><td>Selects all of that row&#39;s keys (on an action track, all its blocks).</td></tr><tr><td>A main key</td><td>Selects everything under it.</td></tr><tr><td>A marker flag</td><td>Renames it.</td></tr><tr><td>A sound&#39;s right edge</td><td>Clears its trim.</td></tr><tr><td>A bar grip</td><td>Resets to the emitter&#39;s own Lifetime.</td></tr><tr><td>A row-height grip</td><td>Resets the row&#39;s height.</td></tr><tr><td>A scene in the list</td><td>Renames it.</td></tr></tbody></table><h4 id="views-and-zoom" tabindex="-1">Views and zoom <a class="header-anchor" href="#views-and-zoom" aria-label="Permalink to &quot;Views and zoom&quot;">​</a></h4><ul><li><strong>The Ease and Channels tabs under the Search box</strong> open that view under the dope rows. Clicking the open one closes it.</li><li><strong>The value axis zooms</strong>: scroll over the 44 px axis in the curve graph to zoom values at the pointer. <kbd>Ctrl+Shift</kbd>+wheel does it anywhere on the graph.</li><li><strong><kbd>Ctrl+Shift</kbd>+wheel</strong> shrinks or grows dope sheet rows (compact rows are 20 px, normal 24).</li><li><strong>Row stripes</strong> make a row&#39;s name line up with its keys. Their strength is tunable (View &gt; Row stripes, Settings &gt; Timeline).</li></ul><h4 id="the-status-bar-is-clickable" tabindex="-1">The status bar is clickable <a class="header-anchor" href="#the-status-bar-is-clickable" aria-label="Permalink to &quot;The status bar is clickable&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Item</th><th>Click it to</th></tr></thead><tbody><tr><td>Snap</td><td>Open the snap menu.</td></tr><tr><td>Auto-key</td><td>Toggle it.</td></tr><tr><td>The frame rate</td><td>Open its menu.</td></tr><tr><td>The length</td><td>Open &quot;Type a length... / End at the playhead / End at the last key&quot;. Type <code>2s</code>, <code>72f</code> or a number in the ruler&#39;s units.</td></tr><tr><td>The particle-cap message</td><td>Open Settings &gt; Effects.</td></tr></tbody></table><h4 id="keying-and-timing" tabindex="-1">Keying and timing <a class="header-anchor" href="#keying-and-timing" aria-label="Permalink to &quot;Keying and timing&quot;">​</a></h4><ul><li><strong>Retiming scales</strong>: dragging the scale handles, or shortening the scene, never deletes keys.</li><li>Insert/Remove time in the ruler menu shifts everything after a point. &quot;Remove the loop region&#39;s time&quot; cuts the loop region out.</li><li><strong><kbd>Shift+K</kbd></strong> (or a double click on an actor&#39;s row header) keys a whole actor. <ul><li>On a rig: every joint, even the ones not keyed yet, never its root. Key that from the root row.</li><li>On anything else: the root.</li></ul></li><li><strong>Frame 0 is kept for you</strong>: the first key you write after frame 0 on a track also keys frame 0, with the value from before you animated it. The option is Settings &gt; Posing &gt; Key frame 0 when it&#39;s missing (also in the Auto-key chevron).</li><li><strong>Call rows</strong>: <kbd>K</kbd> or a double click on an <code>Emit()</code> / <code>Play()</code> row header keys a call at the playhead, copying the key before it (an <code>Emit(20)</code> stays 20).</li><li>Two <code>Play()</code> keys with different settings dropped on one frame both stay (stacked bars).</li></ul><h4 id="bars-sounds-and-emitters" tabindex="-1">Bars, sounds and emitters <a class="header-anchor" href="#bars-sounds-and-emitters" aria-label="Permalink to &quot;Bars, sounds and emitters&quot;">​</a></h4><ul><li><strong>Stacked bars can be re-arranged</strong>: drag a sound bar, burst bar or action block up or down to choose its lane. Right click &gt; Reset lane lets it stack on its own again.</li><li><strong>Sound bars</strong>: trim the start without moving the audio, stretch the speed with <kbd>Ctrl</kbd>+drag, fade with the hover grips, loop with the loop handles.</li><li>A sound row can be made taller (drag the header edge) for bigger waveforms.</li><li>Scrubbing over a sound plays short snippets (Settings &gt; Audio) that end where the playhead&#39;s frame ends.</li><li><strong>Emitter bars</strong>: grips on an <code>Emit()</code> bar set that burst&#39;s particle life; the key keeps its own life. The grips on an emitter&#39;s stream band change the emitter&#39;s Lifetime property.</li></ul><div class="tip custom-block"><p class="custom-block-title">Snap a key to a sound&#39;s peak</p><p>Drag a key near a loud hit and it snaps onto the waveform&#39;s peak. An amber snap line shows, with &quot;snap: Roar peak&quot;.</p></div><h4 id="rows-tracks-and-pasting" tabindex="-1">Rows, tracks and pasting <a class="header-anchor" href="#rows-tracks-and-pasting" aria-label="Permalink to &quot;Rows, tracks and pasting&quot;">​</a></h4><ul><li><strong>Remove many tracks at once</strong>: <kbd>Ctrl</kbd> or <kbd>Shift</kbd> click several object or property headers, then right click one: &quot;Remove N tracks from timeline&quot;.</li><li><strong>Mute / lock</strong> work per actor (Hub or the Timeline row), per joint and per property track.</li><li>Muted rows draw at 50% and are skipped in preview, playback and export.</li><li><strong>Paste to another actor</strong>: select exactly one other actor and paste (or use the key menu&#39;s &quot;Paste to another actor&quot;) to put copied keys on it.</li><li><strong>Paste mirrored</strong> swaps a joint&#39;s keys onto its partner, with the flipped channels negated.</li></ul><h4 id="teammates" tabindex="-1">Teammates <a class="header-anchor" href="#teammates" aria-label="Permalink to &quot;Teammates&quot;">​</a></h4><ul><li><strong>The Scene field has two jobs</strong>: a click opens the scene picker, a right-click opens the Scene menu (Save, Rename, Export, Close).</li><li><strong>A teammate&#39;s flag or avatar</strong> jumps or follows on a click and opens the teammate menu on a right-click. An avatar for someone in another scene opens that scene and follows them.</li><li><strong>+N</strong> at the end of the avatars lists everyone in the place, with where they are and a Follow button each.</li><li><strong>Any input of yours stops following.</strong> The toast&#39;s <strong>Follow</strong> button picks up again.</li><li><strong>Ctrl+Z after a teammate built on your edit</strong> offers <strong>Put back</strong> for their part, so you can undo your own change without losing theirs.</li></ul><div class="info custom-block"><p class="custom-block-title">Studio&#39;s selection</p><p>The Timeline and the Hub set Studio&#39;s selection aside while the pointer is over them, so a stray Delete cannot delete your rig. A Cast row click selects the rig, and it shows in the Explorer once the pointer leaves the Hub. If a stand-in is deleted anyway, a banner offers <strong>Restore</strong>.</p></div><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h3><h4 id="gizmo-and-posing-keys" tabindex="-1">Gizmo and posing keys <a class="header-anchor" href="#gizmo-and-posing-keys" aria-label="Permalink to &quot;Gizmo and posing keys&quot;">​</a></h4><ul><li><strong><kbd>T</kbd></strong> switches between Move &amp; rotate and Resize.</li><li><strong><kbd>R</kbd></strong> cycles Local / Parent / World.</li><li><strong><kbd>Ctrl</kbd></strong> during a drag flips between Studio&#39;s snapping increments and free movement.</li><li><strong><kbd>X</kbd></strong> switches FK and IK and stays. <strong><kbd>Ctrl+[</kbd> / <kbd>Ctrl+]</kbd></strong> change the IK chain length (even mid-drag).</li><li><strong>Hold <kbd>Tab</kbd></strong> to turn about any point of any part (27 snap points per part box). Release and the gizmo goes back to the joint.</li><li><strong><kbd>[</kbd> and <kbd>]</kbd></strong> walk up and down the picked joint&#39;s chain.</li><li><strong><kbd>Esc</kbd> or right click</strong> cancels any gizmo or resize drag and puts the pose back.</li></ul><h4 id="pins" tabindex="-1">Pins <a class="header-anchor" href="#pins" aria-label="Permalink to &quot;Pins&quot;">​</a></h4><ul><li><strong>Tap <kbd>P</kbd></strong> to pin the picked parts.</li><li><strong>Hold <kbd>P</kbd> and click</strong> to pin a spot.</li><li><strong>Hold <kbd>P</kbd> and click a floor or prop</strong> (with parts picked) to anchor their pins to it, so they ride along.</li><li><strong>Unanchor picked pins</strong> (the Pins menu, or the viewport&#39;s right-click <strong>Unanchor pin</strong>) lets them go of it, pinned where they are now.</li><li><strong><kbd>Shift+P</kbd></strong> clears.</li></ul><h4 id="trails-effects-and-keys" tabindex="-1">Trails, effects and keys <a class="header-anchor" href="#trails-effects-and-keys" aria-label="Permalink to &quot;Trails, effects and keys&quot;">​</a></h4><ul><li><strong>Hold <kbd>J</kbd></strong> (or click the stopwatch) to retime keys by sliding their dots along a motion trail.</li><li><strong>Double click a trail</strong> to add a key. <strong><kbd>Alt</kbd></strong> on a tangent handle breaks it.</li><li><strong>Click an effect model in the viewport</strong>, even an invisible, non-clickable holder part, to select it in Studio, then Add actor from selection. <strong><kbd>Alt</kbd>+click</strong> selects just the part.</li><li>Poses are <strong>temporary until keyed</strong>: moving the playhead drops an unkeyed pose. Auto-key keys on release; <kbd>K</kbd> keys picked joints.</li></ul><div class="tip custom-block"><p class="custom-block-title">See the path between keys</p><p>Onion ghosts, trails and pins all read the keys you have <strong>selected in the Timeline</strong>. Select two or more keys to see the path and a ghost on each.</p></div><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h3><h4 id="editing-values" tabindex="-1">Editing values <a class="header-anchor" href="#editing-values" aria-label="Permalink to &quot;Editing values&quot;">​</a></h4><ul><li><strong>Drag any number field</strong> to scrub it (<kbd>Shift</kbd> 10x finer, <kbd>Ctrl</kbd> whole numbers, <kbd>Esc</kbd> puts it back).</li><li><strong>Right click anywhere on a row</strong>: Key at playhead, Remove from timeline, Copy, Paste, Reset to default, Reset to value before animating.</li><li><strong><kbd>K</kbd> over a row</strong> keys it. The diamond cycles animate, key, remove key.</li><li><strong>Select several objects</strong> (Timeline keys or rows, or the Explorer) and edit them together: Mixed values, per-part typing, one undo step.</li><li><strong>Edits made in Studio&#39;s own Properties window</strong> to a property already on the Timeline are recorded: keyed with Auto-key on, a Changed pose with it off.</li></ul><h4 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h4><ul><li><strong>Search covers the whole actor</strong>, not just the picked object. Matches elsewhere are listed under &quot;Elsewhere on {actor}&quot; with a <strong>Show</strong> arrow.</li><li>Clicking a Timeline property row, a key, or a part in the viewport changes what the Inspector shows.</li><li><strong>An actor or its root row?</strong> Both show the actor&#39;s properties. The Stack section lists every stacked row for the actor when its Timeline row or its own root is picked, and only the root&#39;s stack when the Timeline&#39;s root row is the selected one.</li><li>A NumberSequence / ColorSequence row has a <strong>one-value control</strong> before its preview.</li><li>Attributes of any type animate like properties. The <strong>Calls section</strong> keys methods.</li></ul><div class="warning custom-block"><p class="custom-block-title">Decal ids</p><p>A <strong>Decal id</strong> pasted into a texture field says &quot;Not an image: a Decal&quot;. Paste the image&#39;s id instead (a Decal&#39;s Texture holds it). The palette lists the track&#39;s images and the actor&#39;s.</p></div><h3 id="editor-windows" tabindex="-1">Editor windows <a class="header-anchor" href="#editor-windows" aria-label="Permalink to &quot;Editor windows&quot;">​</a></h3><ul><li><strong><kbd>Enter</kbd> = OK, <kbd>Esc</kbd> = Cancel.</strong></li><li><kbd>Ctrl+Z</kbd> / <kbd>Ctrl+Y</kbd> step through the window&#39;s own changes (also the footer&#39;s Undo / Redo).</li><li>Keep several windows open at once, up to 6 per kind.</li><li><strong>Click the sequence graph</strong> to add a point and keep dragging it.</li><li><strong>Double click a gradient stop</strong> to edit its colour in its own picker.</li><li><strong>Presets</strong> replace the shape.</li><li>The <strong>Saved strip</strong> keeps colours, gradients and sequences in the scene for every property.</li><li>A saved sequence larger than the current Range grows the Range to fit.</li></ul><h3 id="scenes-export-and-settings" tabindex="-1">Scenes, export and settings <a class="header-anchor" href="#scenes-export-and-settings" aria-label="Permalink to &quot;Scenes, export and settings&quot;">​</a></h3><h4 id="scenes" tabindex="-1">Scenes <a class="header-anchor" href="#scenes" aria-label="Permalink to &quot;Scenes&quot;">​</a></h4><ul><li><strong>Scenes can live in any folder</strong>: move a scene folder anywhere and it is still listed and saved there. Export&#39;s play line then starts with <code>AcesMotion.RegisterFolder(...)</code>.</li><li><strong>Scene &gt; Save as...</strong> makes a copy and opens it with its name ready to type. <strong>Duplicate</strong> copies without opening.</li></ul><h4 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h4><ul><li><strong>Export &gt; Preview id</strong> makes a test AnimationId for the session, so the rig plays the exported clip without uploading.</li><li>After the first upload, paste the id. Then you can pick &quot;Overwrite an existing asset...&quot; next time and keep the same id in games.</li><li><strong>Scene as text</strong> (Export) + <strong>Import &gt; Scene text</strong> moves a whole scene between places.</li><li><strong>Create N scenes / Save as model</strong> (Export &gt; AcesMotion runtime) split a multi-rig scene into one scene per rig and pack them for other games.</li></ul><h4 id="settings-and-tooltips" tabindex="-1">Settings and tooltips <a class="header-anchor" href="#settings-and-tooltips" aria-label="Permalink to &quot;Settings and tooltips&quot;">​</a></h4><ul><li><strong>Reset this group</strong> at the bottom of a Settings page restores that page&#39;s defaults (and its rebindable keys) after a confirm. It never touches your mirror rules or presets.</li><li><strong>Gizmo size</strong>: click the value on the slider to type one.</li><li><strong>Icon style</strong> switches every icon live.</li><li>Every control has a <strong>tooltip</strong>, and a disabled control&#39;s tooltip says why.</li><li>After the first tooltip, tooltips appear instantly while you move across neighbouring controls.</li></ul>',44)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
